(() => {
  'use strict';
  const ids=['main-menu','new-career','load-game','settings','accessibility','laboratory','experiment-detail','pause-menu','save-game','chapter-select','scene-briefing','dialogue','decision','history-notes','ending','sailing-hud','sea-chart','destination-detail','route-plan','weather-wind','sea-encounter'];
  const data=()=>window.GAME_UI_DATA;
  const PORTS={
    澳门:{title:'澳门 · 香山澳',region:'广东沿岸',entry:'货行引介与船货清单',supply:'淡水、粮食、索具',goods:'白糖与舶来器物',contact:'黄程',image:'zheng_a1_s1',x:220,y:519,distance:380,days:4,notice:'来往各船各有凭据。会说几句话，还得能把约定讲清楚。',facilities:['货栈','补给','通事']},
    厦门:{title:'厦门 · 中左所',region:'福建沿岸',entry:'核对船籍与泊位',supply:'船坞、木料、粮水',goods:'生丝、瓷器、铁料',contact:'本港米行',image:'zheng_a4_s1',x:330,y:400,distance:36,days:1,notice:'码头边的旧识，记得船的名字，也记得尚未结清的事。',facilities:['船坞','市场','补给']},
    泉州:{title:'泉州 · 刺桐岸',region:'福建沿岸',entry:'按本港约定查验',supply:'补帆、木作、粮水',goods:'瓷器、布匹',contact:'旧日乡人',image:'zheng_a1_s2',x:360,y:338,distance:64,days:1,notice:'故乡并不意味着每一扇门都还为你开着。',facilities:['木作','市场','家信']},
    大员:{title:'大员 · 外海锚地',region:'台湾西岸',entry:'先问当日往来限制',supply:'淡水、临时修补',goods:'鹿皮与转运货',contact:'熟识通事',image:'zheng_a3_s1',x:468,y:441,distance:180,days:2,notice:'各方凭据与传来的消息，须分清是谁给的、给谁看的。',facilities:['锚地','补给','情报']},
    平户:{title:'平户 · 川内浦',region:'九州西岸',entry:'熟识船主引介',supply:'淡水、米粮、缆绳',goods:'生丝买卖与回程货',contact:'吉平',image:'zheng_a2_s1',x:790,y:135,distance:760,days:7,notice:'货物有买主，川内浦有一间等船回来的屋。',facilities:['市场','补给','家书']},
    吕宋:{title:'吕宋 · 马尼拉外海',region:'南方航路',entry:'通事与入港凭据',supply:'需向来船核实',goods:'转运货与白银消息',contact:'南下船主',image:'zheng_a3_s9',x:575,y:574,distance:690,days:6,notice:'海图上有名字的地方，未必已经有你可以靠泊的位置。',facilities:['查验','转运','情报']}
  };
  const LABS=[
    {id:'water-contact',name:'船体与水面的接触',subtitle:'透射、消光与动态水线',scene:'zheng_a4_s7',status:'已有独立记录',scope:'固定船位、光照和相机，辨认水下船壳与水线边缘。',baseline:'原透射参数',candidate:'较强消光',question:'船已经浸水，为什么仍像浮在海面之上？',observations:['保持船体位置与波面一致','区分透射、倒影与几何误差','近拍水沫仍需继续改善'],records:['18 张首轮受控原帧','8 张参数细化原帧','正式接入参数仍需按船型复核'],source:'ship-water-contact-optics-research-2026-10-14.md'},
    {id:'wake-field',name:'尾迹与局部白沫',subtitle:'速度响应、转向与停船消散',scene:'zheng_a5_s7',status:'待补本轮对照',scope:'同船、同速、同一接受时刻，观察尾流宽度与转弯连续性。',baseline:'原双线尾流',candidate:'交互尾迹场',question:'转向与停船以后，水面是否还记得刚才的船？',observations:['双侧尾迹不能被接触水沫替代','停船后应自然消散','转弯内外侧保留连续轨迹'],records:['已有历史实验与修复记录','本轮界面不生成 GPU 数据','完整航行性能需另行测量'],source:'interactive-wake-delivery-2026-10-14.md'},
    {id:'weather-shadow',name:'天气、云与投影',subtitle:'连续漂移、出镜回收与云海合成',scene:'zheng_a3_s10',status:'尚未接入网页',scope:'固定随机种子与相机，查看旧云离场、新云入场的连续过程。',baseline:'逻辑中心直接回收',candidate:'有界三实例显示',question:'云的逻辑重置，能否不在视野中突然跳走？',observations:['主视锥与镜像视锥一并保护','旧云完整出镜后再回收','实例数量必须有界'],records:['历史独立实验保存 50 张原帧','每组 129 个接受时刻','不代表整场游戏帧率'],source:'world-cloud-lifecycle-2026-10-15.md'}
  ];
  const sampleSave=(name='平户归航 · 雨后',hull=84,silver=2180)=>({name,hull,silver,snapshot:{demoFixture:true}});
  function view(screen,state){
    const v={...state,settings:{...state.settings},stock:{...state.stock},saves:[...(state.saves||[])]},p=state.previewScenario||'';
    v.worldScenario=p;v.destination=PORTS[v.destination]?v.destination:'平户';
    switch(screen.id){
      case 'main-menu':if(p==='没有演示存档')v.menuEmpty=true;if(p==='已有航次存档')v.saves=[sampleSave()];if(p==='全部页面可预览')v.menuExplore=true;break;
      case 'new-career':v.careerStage=p;if(p==='确认新档')v.careerMode='海上生涯';if(p==='保留既有存档')v.saves=[sampleSave()];break;
      case 'load-game':if(p==='自动档')v.saves=[sampleSave('自动记录 · 厦门泊位',92,1640)];if(p==='手动档')v.saves=[null,sampleSave('手记 · 北上之前',68,3200)];if(p==='不兼容说明')v.saves=[sampleSave('旧版航程 · 版本待核')];if(p==='空档位')v.saves=[];break;
      case 'save-game':if(p==='确认覆盖'){v.saves=[sampleSave()];v.confirmSaveSlot=0;}if(p==='保存成功'){v.saves=[sampleSave('厦门外海 · 出港前',state.hull,state.silver)];v.savedPreview=true;}if(p==='空档位'){v.saves=[];v.emptySlotSelected=true;}break;
      case 'settings':if(p==='未修改')v.settingsPristine=true;if(p==='待应用')Object.assign(v.settings,{music:35,effects:80,quality:'流畅'});if(p==='已保存')Object.assign(v.settings,{music:45,effects:65,quality:'高画质'});break;
      case 'accessibility':if(p==='常规对比')v.assistSample='普通航行';if(p==='高对比')Object.assign(v.settings,{highContrast:true,colorAssist:true});if(p==='大字模式')v.settings.text=135;if(p==='减少动态')v.settings.reducedMotion=true;break;
      case 'experiment-detail':if(p==='基线')v.labVariant='基线';if(p==='候选')v.labVariant='候选';if(p==='报告待补')v.labTopic='wake-field';if(p==='原生运行另开')v.labTopic='weather-shadow';break;
      case 'chapter-select':if(p==='未开始')v.selectedAct=data().acts[0].id;if(p==='进行中')v.selectedAct=data().acts[2].id;if(p==='已回顾')v.selectedAct=data().acts[5].id;break;
      case 'scene-briefing':if(p==='准备阶段')v.briefingChecklist=true;if(p==='剧情前提已定')v.showCanon=true;if(p==='缺少出航条件'){v.hull=24;v.stock.grain=4;v.departureBlocked=true;}break;
      case 'dialogue':if(p==='普通对白'){v.selectedScene='zheng_a2_s1';v.dialogueLine=1;}if(p==='重要承诺'){v.selectedScene='zheng_a3_s7';v.dialogueLine=2;v.dialogueLog=true;}if(p==='人物拒绝'){v.selectedScene='zheng_a3_s5';v.dialogueLine=4;}if(p==='历史节点'){v.selectedScene='zheng_a4_s4';v.dialogueLine=0;}break;
      case 'decision':if(p==='固定剧情步骤')v.fixedDecision=true;if(p==='资源不足')v.silver=80;if(p==='结果待发生')v.choice='keep-hull';if(p==='局部方案预览')v.decisionCompare=true;break;
      case 'history-notes':if(p==='历史骨架')v.selectedScene='zheng_a5_s4';if(p==='晚出材料')v.selectedScene='zheng_a2_s3';if(p==='研究推断')v.selectedScene='zheng_a2_s1';if(p==='原创场面')v.selectedScene='zheng_a4_s7';break;
      case 'sailing-hud':if(p==='顺风前进'){v.speed=9.2;v.voyageProgress=36;}if(p==='逆风辅助'){v.speed=4.6;v.weather='逆风';v.heading=32;v.voyageProgress=17;}if(p==='接近目的地'){v.speed=2.4;v.voyageProgress=96;}if(p==='应急状态'){v.hull=21;v.speed=3.1;v.weather='风浪';v.voyageProgress=54;}break;
      case 'sea-chart':if(p==='已知港口')v.chartFilter='known';if(p==='情报未核'){v.destination='吕宋';v.chartFilter='unverified';}if(p==='当前航路'){v.routeConfirmed=true;v.chartFilter='route';}if(p==='航区受限'){v.destination='大员';v.chartFilter='restricted';}break;
      case 'destination-detail':if(p==='需要凭据')v.destination='吕宋';if(p==='接近靠泊范围')v.nearPort=true;if(p==='设施受损')v.destination='厦门';if(p==='可进港')v.entryApproved=true;break;
      case 'route-plan':if(p==='沿岸稳妥')v.route='沿岸';if(p==='外海较快')v.route='直航';if(p==='补给不足')v.stock.grain=3;if(p==='航路已定')v.routeConfirmed=true;break;
      case 'weather-wind':v.weatherMode=p||'当前';break;
      case 'pause-menu':if(p==='战术暂停')v.pauseContext='battle';if(p==='尚有未保存变更')v.unsavedChanges=true;if(p==='航行暂停')v.pauseContext='voyage';break;
    }
    return v;
  }
  const port=state=>PORTS[state.destination]||PORTS.平户;
  const midway=state=>({澳门:'厦门沿岸换水',厦门:'近岸直接回港',泉州:'沿岸短程守望',大员:'过海后核对锚地',平户:'大员外缘问风补给',吕宋:'大员以南核实风信'}[state.destination]||'沿岸核对风信');
  const settingTabs=id=>window.GameUI.ui.tabs([{id:'settings',label:'画面与声音'},{id:'accessibility',label:'操作与辅助'},{id:'load-game',label:'读取航程'}],id);
  const openScene=(ui,id,label,target='scene-briefing',cls='button')=>ui.action('open',label,cls,{key:'selectedScene',value:id,target});
  const detailRows=rows=>`<dl class="world-detail-list">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  function storyScene(state){const a=data().acts.find(x=>x.id===state.selectedAct);return data().scenes.find(s=>s.id===state.selectedScene)||data().scenes.find(s=>s.id===a?.first)||data().scenes[0];}
  function chart(ui,route=false,state={}){
    const selected=PORTS[state.destination]?state.destination:'平户',end=PORTS[selected],mini=state.miniMap;
    const coast={澳门:'M385 347Q355 380 330 400Q285 455 220 519',厦门:'M385 347Q345 370 330 400',泉州:'M385 347Q370 325 360 338',大员:'M385 347Q430 390 468 441',平户:'M385 347Q445 390 468 441Q650 340 790 135',吕宋:'M385 347Q440 400 468 441Q500 505 575 574'};
    const path=state.route==='直航'?`M385 347Q550 420 ${end.x} ${end.y}`:coast[selected];
    return `<div class="nautical-map ${mini?'world-minimap':'world-chart'} ${state.chartFilter==='restricted'?'has-restriction':''}"><svg viewBox="0 0 1000 660" role="img" aria-label="当前船位至${ui.e(selected)}的航区示意"><path class="map-land" d="M0 0H620L580 50 510 60 490 95 448 122 460 154 418 185 410 216 385 252 400 275 360 297 360 338 335 363 330 400 300 420 275 456 235 475 216 519 165 535 140 580 90 590 60 660H0Z"/><path class="map-land" d="M480 351l16 18-2 38-18 53-22 20-9-15 8-55zM788 110l36-30 30 12-15 21-12 27-25 18-27-7-1-22zM850 80l36-22 23-21 18 8-8 27-38 27-28-5zM909 38l28-25 38-13 25 0v21l-43 17-30 18zM550 536l17-14 15 12-4 35 25 22-10 34-18-8-9-40-20-11zM573 640l35-4 17 24h-52z"/><text class="map-label" x="205" y="245">福 建</text><text class="map-label" x="500" y="401">大 員</text><text class="map-label" x="808" y="180">日 本</text><text class="world-map-sea" x="660" y="420">东 海</text>${state.chartFilter==='restricted'?'<ellipse class="world-restricted-area" cx="468" cy="441" rx="105" ry="80"/><text x="490" y="512" class="world-map-warning">凭据待核航区</text>':''}<path class="map-route ${state.routeConfirmed?'confirmed':''}" d="${path}"/>${route?`<path class="world-alternate-route" d="M385 347Q520 250 ${end.x} ${end.y}"/>`:''}${Object.entries(PORTS).map(([name,p])=>`<g class="map-port ${name===selected?'is-selected':''}" data-action="open" data-key="destination" data-value="${name}" data-target="destination-detail" role="button" tabindex="0" aria-label="查看${name}${name===selected?'，当前目的港':''}"><circle cx="${p.x}" cy="${p.y}" r="${name===selected?11:7}"/><circle class="port-halo" cx="${p.x}" cy="${p.y}" r="${name===selected?24:16}"/><text x="${p.x+21}" y="${p.y+5}">${name}${state.chartFilter==='unverified'&&name==='吕宋'?' ？':''}</text></g>`).join('')}<g transform="translate(385 347) rotate(${state.heading||30})"><path class="world-ship-marker" d="M0-18L11 15 0 8-11 15z"/></g><g class="world-map-compass" transform="translate(880 540)"><circle r="40"/><path d="M0-50L7-7 50 0 7 7 0 50-7 7-50 0-7-7z"/><text y="-58" text-anchor="middle">北</text></g></svg>${mini?'':`<div class="world-map-key"><span><i class="key-ship"></i> 当前位置</span><span><i class="key-port"></i> 目的港：${ui.e(selected)}</span><span><i class="key-route"></i> ${state.routeConfirmed?'已确认航路':'航路草案'}</span><small>航区示意 · 非实测海图</small></div>`}</div>`;
  }
  function menu(screen,state,ui){
    const saved=state.saves.find(Boolean);
    return `<div class="menu-scene world-menu" style="background-image:url('assets/main-menu-v2.png')"><div class="menu-copy"><p class="context-label">郑芝龙的海上半生 · 1621—1646</p><h1>海上明旗</h1><p class="sub-title">一 官 入 海</p><nav class="menu-links" aria-label="主菜单">${saved?ui.action('load','继续航程 <span>›</span>','button',{slot:state.saves.indexOf(saved)}):ui.action('notice','继续航程 <small>暂无记录</small>','button',{disabled:true})}${ui.go('new-career','新生涯 <span>›</span>')}${ui.go('load-game','读取航程 <span>›</span>')}${ui.go('chapter-select','故事篇章 <span>›</span>')}${ui.go('laboratory','实验室 <span>›</span>')}${ui.go('settings','设置 <span>›</span>')}</nav>${saved?`<div class="world-menu-record"><small>最近的航程</small><strong>${ui.e(saved.name)}</strong><span>船体 ${saved.hull}% · 现银 ${saved.silver.toLocaleString()} 两</span></div>`:state.menuEmpty?`<div class="world-menu-record"><strong>第一张航程记录，尚未写下</strong><span>从澳门的货栈启程，在暂停菜单保存自己的航程。</span>${ui.go('new-career','从1621年开始','button quiet')}</div>`:`<p class="menu-note">从一张借来的船位开始。<br>海上有路，路上有人；每一次靠岸，都有人等你归来。</p>`}</div>${state.menuExplore?`<aside class="world-menu-explore"><p class="context-label">界面巡览</p><h2>先看一眼，海上的日子</h2>${ui.go('sailing-hud','出海 · 航行与风向')}${ui.go('ship-overview','检船 · 人、船与货')}${ui.go('letters','靠岸 · 家书与牵挂')}${ui.go('battle-hud','临阵 · 舰队与炮火')}</aside>`:'<div class="scene-caption">风起刺桐　帆向东海</div>'}</div>`;
  }
  function career(screen,state,ui){
    const confirming=state.careerStage==='确认新档',preserve=state.saves.filter(Boolean).length;
    return ui.pageHead('新生涯','从借来的船位开始','1621年，一官初到澳门。你还没有自己的船，却已想去更远的地方。')+`<div class="career-panel"><div class="career-portrait" style="background-image:url('${ui.sceneURL('zheng_a1_s5')}')"><div>${ui.pill('历史改编 · 郑芝龙')}<h2>一官</h2><p>肯学话，敢押注。<br>还得学会：替谁答应，就得替谁承担。</p></div></div><section><h2 class="section-title">${confirming?'核对这段航程':'选择这段航程的节奏'}</h2><div class="decision-options">${['故事体验','海上生涯'].map(x=>ui.action('set',`<strong>${x}</strong><p>${x==='故事体验'?'航行与战斗更宽容，专心体验人物与故事。':'保留经营、船员与战损取舍，风向仍不阻断基本行动。'}</p>`,`decision-option ${(state.careerMode||'故事体验')===x?'selected':''}`,{key:'careerMode',value:x})).join('')}</div><div class="stat-row">${ui.metric('起点','澳门')}${ui.metric('身份','随船伙计')}${ui.metric('私有船只','0','艘')}</div>${preserve?`<div class="world-status"><h3>已有 ${preserve} 份航程记录</h3><p>${ui.e(state.saves.find(Boolean).name)}将继续保留。新生涯进入故事后，由你选择新的存档位置。</p>${ui.go('load-game','先核对旧航程','button quiet')}</div>`:state.careerStage==='首次开始'?`<ol class="world-start-steps"><li><b>听清约定</b><span>先在货栈学会把话说准。</span></li><li><b>完成第一程</b><span>跟船出海，再慢慢有自己的船。</span></li><li><b>留下航程</b><span>暂停时保存，不必一次走完。</span></li></ol>`:`<p class="inline-note">出生、受抚、料罗湾及父子分途等历史节点保留；私人对话、伙伴与具体冒险为文学创作。</p>`}${confirming?detailRows([['航程节奏',ui.e(state.careerMode)],['开篇','第一幕 · 澳门货栈'],['存档处理','保留已有记录，另行选择位置']]):''}<div class="toolbar">${openScene(ui,'zheng_a1_s1',confirming?'确认 · 走入澳门':'启程','scene-briefing','button primary')}${ui.go('main-menu','返回')}</div></section></div>`;
  }
  function saves(screen,state,ui){
    const loading=screen.id==='load-game',unavailable=['存储不可用','不兼容说明'].includes(state.worldScenario),empty=!state.saves.some(Boolean);
    return ui.pageHead('航程记录',loading?'读取航程':'保存航程','船、人、货物与尚未兑现的约定，一起留在这一页。',ui.go('pause-menu','返回'))+`<div class="save-layout"><aside class="save-context"><img src="${ui.sailingImage}" alt="福建外海的顺风号"><p class="context-label">当前航次 · 福建外海</p><h2>顺风号 · 出港前</h2>${detailRows([['旗舰船体',state.hull+'%'],['随船人数',state.crew+' 人'],['现银',Number(state.silver).toLocaleString()+' 两'],['货舱',ui.cargoUsed(state)+' / '+(state.cargoCapacity||350)+' 格']])}<p class="muted small">此网页的航程记录保留在本次会话，刷新后重置。</p></aside><section>${!loading?`<label class="field">给这段航程留个名字<input id="save-name" value="${ui.e(state.saveNameDraft??(state.emptySlotSelected?'第一份航海手记':'厦门外海 · 出港前'))}" maxlength="40" ${unavailable?'disabled':''}></label>`:''}${unavailable?`<div class="world-status is-warning" role="status"><h3>${loading?'档案版本尚待核对':'当前无法保存'}</h3><p>${loading?'保留这份旧记录；选择兼容的航程，或先返回，不要覆盖原件。':'请先保留眼前航程，恢复存储后再试。此时不会写入任何档位。'}</p>${ui.go(loading?'new-career':'sailing-hud',loading?'另起新生涯':'继续眼前航程','button')}</div>`:''}${state.savedPreview?'<div class="world-status is-success"><h3>航程已写入 01 号档位</h3><p>人、船、货物和当前约定已一同记下，可以前往读取页核对。</p></div>':''}${[0,1,2].map(n=>{const saved=state.saves[n],confirm=state.confirmSaveSlot===n;return `<article class="save-slot ${saved?'has-record':'is-empty'} ${confirm?'is-confirming':''} ${state.emptySlotSelected&&n===0?'selected':''}"><span class="slot-number">0${n+1}</span><div><small class="muted">${loading&&state.worldScenario==='自动档'&&n===0?'自动记录':n===0?'主要航程':'备用航程'}</small><h3>${ui.e(saved?.name||'尚未写下的航程')}</h3><p class="small muted">${saved?`船体 ${saved.hull}% · 银两 ${saved.silver.toLocaleString()} 两`:'这里可留下下一段航程。'}</p>${confirm?'<p class="negative small">此记录将被当前航次替换；请核对名称与船况。</p>':''}</div>${ui.action(loading?'load':'save',loading?saved?'读取航程':'暂无记录':confirm?'确认覆盖':saved?'覆盖此记录':state.emptySlotSelected&&n===0?'存入空档 01':'保存在此','button '+(!loading||saved?'primary':''),{slot:n,disabled:unavailable||(loading&&!saved)})}${confirm?ui.action('set','取消覆盖','button quiet',{key:'confirmSaveSlot',value:''}):''}</article>`;}).join('')}${loading&&empty?`<div class="world-empty-record"><h3>${state.worldScenario==='空档位'?'这一页还没有可读取的航程':'先留下第一份航海手记'}</h3><p>读取需要一份已保存的记录。${state.worldScenario==='空档位'?'返回眼前航次，再选择一个空档保存。':'从故事开篇启程，或把当前演示航次保存在这里。'}</p>${ui.go(state.worldScenario==='空档位'?'save-game':'new-career',state.worldScenario==='空档位'?'去保存当前航程':'开始新生涯','button primary')}</div>`:`<p class="inline-note">${loading?'读取会恢复当时的银两、库存、船员、设置和流水。':'重要决定之前，可以另存一份；覆盖已有航程需要再次确认。'}</p>`}</section></div>`;
  }

  function settings(screen,state,ui){
    const assist=screen.id==='accessibility',s=state.settings,p=state.worldScenario;
    const range=(key,title,desc,min,max,fallback)=>`<div class="option-row"><div><label for="setting-${key}">${title}</label><small>${desc}</small></div><label><input id="setting-${key}" data-setting="${key}" type="range" min="${min}" max="${max}" value="${s[key]??fallback}"><output>${s[key]??fallback}</output></label></div>`;
    const check=(key,title,desc)=>`<div class="option-row"><div><label for="setting-${key}">${title}</label><small>${desc}</small></div><label><input id="setting-${key}" data-setting="${key}" type="checkbox" ${s[key]?'checked':''}><span>${s[key]?'已开启':'未开启'}</span></label></div>`;
    const select=(key,title,options,fallback)=>`<div class="option-row"><div><label for="setting-${key}">${title}</label><small>当前选择：${ui.e(s[key]||fallback)}</small></div><label><select id="setting-${key}" data-setting="${key}" aria-label="${title}">${options.map(x=>`<option ${x===(s[key]||fallback)?'selected':''}>${x}</option>`).join('')}</select></label></div>`;
    return ui.pageHead('偏好设置',assist?'按你的方式出海':'让海风听得清楚',assist?'读字、辨认和下令，都留有适合自己的方式。':'声音保留层次，画面服从你的阅读与操作。')+settingTabs(screen.id)+`<div class="world-settings-layout"><section>${assist?`<div class="world-settings-section"><h2>文字与辨认</h2>${range('text','文字大小','关键正文、按钮与对白同步放大。',100,140,100)}${check('highContrast','提高界面对比','为文字与操作面增加明暗区分。')}${check('colorAssist','状态图形辅助','敌我、受损与装填同时使用形状和文字。')}</div><div class="world-settings-section"><h2>镜头与指令</h2>${check('reducedMotion','减少动态效果','减弱过渡；必要反馈继续显示。')}${check('navigationAssist','逆风航行辅助','帮助转向，不让逆风切断基本行动。')}${check('holdToToggle','用切换代替长按','观察模式可按一次进入、再次退出。')}</div>`:`<div class="world-settings-section"><h2>声音</h2>${range('music','音乐','让乐声退到人物与海风之后。',0,100,60)}${range('effects','环境与战斗','海浪、帆索、船壳与炮声的总体响度。',0,100,75)}${range('voice','人物对白','为日后语音保留独立响度。',0,100,85)}</div><div class="world-settings-section"><h2>画面</h2>${select('quality','画面预设',['均衡','高画质','流畅'],'均衡')}${select('windowMode','窗口模式',['无边框窗口','全屏','窗口'],'无边框窗口')}${check('subtitles','始终显示字幕','对白文字与说话人始终可读。')}</div>`}<div class="world-setting-footer"><p>${p==='待应用'?'正在比较另一组参数；滑动或选择后会即时更新本次会话。':p==='已保存'?'这组偏好已留在当前会话；音量为音乐45、环境65。':p==='未修改'?'当前使用默认偏好。':'本次会话即时应用；网页不改变系统音量与原生游戏设置。'}</p>${ui.action('settings-reset','恢复默认','button',{disabled:!!state.settingsPristine})}</div></section><aside class="world-settings-aside">${assist?`<h2>即时阅读示例</h2><div class="world-a11y-demo ${s.highContrast?'high-contrast':''}" style="font-size:${16*(Number(s.text||100)/100)}px"><p class="context-label">${state.assistSample||'顺风号 · 福建外海'}</p><h3>船体受损，需要修补</h3><p>主帆仍可使用。收拢队形，先到最近的避风处。</p><div class="world-a11y-signals"><span>${s.colorAssist?'△ ':''}受损 28%</span><span>${s.colorAssist?'✓ ':''}主帆可用</span></div></div><p class="small muted">${s.reducedMotion?'减少动态已开启：以静态进度和文字确认指令。':'必要动效用于反馈装填、选择和到达。'}${s.highContrast?'当前为高对比配色。':''}</p>`:`<h2>操船与镜头</h2><ul class="world-keyboard-list"><li><kbd>左键</kbd><span>点海面设定航向</span></li><li><kbd>滚轮</kbd><span>拉近／拉远</span></li><li><kbd>右键拖动</kbd><span>环绕观察</span></li><li><kbd>空格</kbd><span>暂停指令</span></li><li><kbd>Esc</kbd><span>打开暂停菜单</span></li></ul><p class="small muted">松开右键保留观察角度；随时回到跟船视角。</p>`}${ui.go('tutorial','查看操作教学','button')}${assist?ui.go('sailing-hud','回到海上看看','button quiet'):ui.go('accessibility','文字、辨认与动态','button quiet')}</aside></div>`;
  }
  function laboratory(screen,state,ui){
    if(screen.id==='laboratory'){
      const p=state.worldScenario,topics=p==='已验证'?[LABS[0]]:p==='待测'?[LABS[1]]:p==='尚未接入'?[LABS[2]]:LABS;
      return ui.pageHead('独立课题 · 可复验记录','实验室','从一个明确的问题开始，保留基线、候选和失败的记录。')+`<div class="world-port-selector">${['全部课题','已验证','待测','尚未接入'].map(x=>ui.action('set',x,`button ${(p||'全部课题')===x?'selected':''}`,{key:'previewScenario',value:x==='全部课题'?'':x})).join('')}</div><div class="world-lab-topics">${topics.map(t=>`<article class="world-lab-topic"><img src="${ui.sceneURL(t.scene)}" alt="${ui.e(t.name)}的叙事情境插图"><p class="context-label">${ui.e(t.status)}</p><h2>${ui.e(t.name)}</h2><p>${ui.e(t.question)}</p><small>${ui.e(t.subtitle)}</small>${ui.action('open','打开这项课题 '+ui.icon('arrow'),'button',{key:'labTopic',value:t.id,target:'experiment-detail'})}</article>`).join('')}</div><div class="world-status"><h3>一份实验，回答一个问题</h3><p>网页展示课题资料与对照界面。原生实验、GPU 原帧和实际性能保留各自的来源与适用范围；历史记录不等于本轮重新验收。</p></div>`;
    }
    const t=LABS.find(x=>x.id===state.labTopic)||LABS[0],variant=state.labVariant||'对照总览',candidate=variant==='候选',baseline=variant==='基线',pending=state.worldScenario==='报告待补',native=state.worldScenario==='原生运行另开';
    const diagram=t.id==='weather-shadow'?`<path d="${candidate?'M50 90Q220 70 390 95T750 90':'M50 90H330M520 90H750'}" stroke="#e7d7a0" stroke-width="3" fill="none"/><circle cx="${candidate?350:530}" cy="90" r="24" fill="#d8dccc55"/><text x="40" y="160" fill="#f1e6cb" font-size="18">${candidate?'连续出镜，再回收':'可见范围中的位置跳变'}</text>`:t.id==='wake-field'?`<path d="${candidate?'M400 150Q370 220 250 320M440 150Q470 240 620 320':'M400 150L350 320M440 150L490 320'}" fill="none" stroke="#e6e9d3aa" stroke-width="${candidate?14:5}"/><text x="40" y="310" fill="#f1e6cb" font-size="18">${candidate?'转向轨迹连续保留':'双线基线示意'}</text>`:`<path d="M230 220Q410 ${candidate?248:226} 590 220" fill="none" stroke="${candidate?'#eadfb8':'#99c5cc'}" stroke-width="${candidate?7:3}"/><path d="M280 235Q410 270 540 235" fill="none" stroke="#9ab9b7" opacity="${candidate?.25:.8}" stroke-width="18"/><text x="40" y="310" fill="#f1e6cb" font-size="18">${candidate?'较强消光：减弱水下船壳':'基线：水下船壳辨识度较高'}</text>`;
    return ui.pageHead('实验室 · '+t.subtitle,t.name,t.scope,ui.go('laboratory','课题目录'))+`<div class="world-lab-detail"><section><div class="world-lab-view"><img src="${t.id==='weather-shadow'?ui.sceneURL(t.scene):ui.sailingImage}" alt="${ui.e(t.name)}界面观察背景"><span>${ui.e(variant)} · 图解示意</span><svg viewBox="0 0 800 350" aria-label="${ui.e(variant)}观察图解" role="img">${diagram}</svg></div><p class="world-lab-caption">图解表达观察位置与比较关系；背景为界面插图，不是该参数下的原生 GPU 实拍。</p><div class="toolbar">${ui.action('set','基线方案',`button ${baseline?'selected':''}`,{key:'labVariant',value:'基线'})}${ui.action('set','候选方案',`button ${candidate?'selected':''}`,{key:'labVariant',value:'候选'})}${ui.action('set','对照总览',`button ${!baseline&&!candidate?'selected':''}`,{key:'labVariant',value:'对照总览'})}</div><div class="world-lab-metrics"><div><span class="small muted">比较变量</span><strong>${ui.e(candidate?t.candidate:t.baseline)}</strong><p>${candidate?'仅改变这一项候选条件':'保留比较起点'}</p></div><div><span class="small muted">时刻与镜头</span><strong>同条件</strong><p>独立记录中固定</p></div><div><span class="small muted">本页结果</span><strong>${pending?'等待原件':native?'需另开原生':'资料对照'}</strong><p>${pending?'不填造性能数值':'不代表整体帧率'}</p></div></div></section><aside><h2>先看什么</h2><ul class="world-lab-checks">${t.observations.map(x=>`<li>${ui.e(x)}</li>`).join('')}</ul><section class="world-lab-records"><h3>${pending?'报告仍缺哪些内容':'已有资料与边界'}</h3>${(pending?['补入相同初态的候选截图','补入接受时刻与参数回执','保留失败样本，再给结论']:t.records).map(x=>`<p class="small">${ui.e(x)}</p>`).join('')}<code>docs/research/${ui.e(t.source)}</code></section>${native?`<div class="world-status"><h3>在原生实验室运行</h3><p>启动项目后，由首页进入实验室，选择对应课题。网页不启动 Godot，也不生成运行回执。</p></div>`:''}<div class="toolbar">${ui.action('notice',native?'已了解原生入口':'查看运行方式','button',{message:'原生项目首页 → 实验室 → '+t.name+'。请按课题记录固定初态与证据。'})}${ui.go('sailing-hud','回到航行','button quiet')}</div></aside></div>`;
  }
  function chapters(screen,state,ui){
    const act=data().acts.find(a=>a.id===state.selectedAct)||data().acts[0],scenes=data().scenes.filter(s=>s.act===act.title),p=state.worldScenario;
    const status=p==='未开始'?'从第一句约定开始':p==='进行中'?'当前回顾：第三幕的同伴与分利':p==='已回顾'?'六幕已读，仍可重回任何一场':p==='原型全解锁'?'全部四十三场可自由巡览':'选择一幕，展开其中的场次';
    return ui.pageHead('六幕 · 四十三场','海上半生','有些路把人送回家，有些路将一家人分开。')+`<div class="chapter-grid">${data().acts.map((a,i)=>`<button class="chapter-tile ${a.id===act.id?'selected':''}" data-action="set" data-key="selectedAct" data-value="${a.id}" aria-pressed="${a.id===act.id}"><img src="../../../narrative/zheng-zhilong/${a.cover}" alt="${ui.e(a.title)}"><div><span class="small muted">第${'一二三四五六'[i]}幕 · ${ui.e(a.years)}</span><h2>${ui.e(a.title)}</h2><p>${p==='已回顾'?'可重读':p==='原型全解锁'?'自由预览':a.id===act.id?'正在展开':'展开场次'}</p></div></button>`).join('')}</div><section class="chapter-detail"><div><p class="context-label">${ui.e(act.years)}</p><h2>${ui.e(act.title)}</h2><p>${ui.e(act.synopsis)}</p><div class="world-chapter-progress" aria-label="六幕进度">${data().acts.map((_,i)=>`<i class="${p==='已回顾'||i<data().acts.indexOf(act)?'done':''}"></i>`).join('')}</div><p>${status}</p><div class="toolbar">${openScene(ui,act.first,p==='已回顾'?'重读本幕':'从本幕开篇','scene-briefing','button primary')}${ui.go('history-notes','读史注','button quiet')}</div></div><ol class="scene-list">${scenes.map((s,i)=>`<li>${openScene(ui,s.id,`<span class="scene-index">${String(i+1).padStart(2,'0')}</span><span><strong>${ui.e(s.title)}</strong><small>${ui.e(s.year)}</small></span>${ui.icon('arrow')}`,'scene-briefing','scene-link')}</li>`).join('')}</ol></section>`;
  }

  function briefing(screen,state,ui){
    const s=storyScene(state),beat=s.dramaticBeat||{},blocked=state.departureBlocked;
    return `<section class="world-briefing" style="background-image:url('${ui.sceneURL(s.id)}')"><div class="cinema-copy"><p class="context-label">${ui.e(s.year)} · ${ui.e(s.act)}</p><h1>${ui.e(s.title)}</h1><p class="world-briefing-location">${ui.e(s.location||'海上与岸间')}</p><p>${ui.e(s.summary)}</p><div class="toolbar">${blocked?ui.action('notice','先备妥船与粮水','button primary',{disabled:true}):ui.go('dialogue','走入故事','button primary')}${ui.go('chapter-select','返回篇章')}${ui.go('history-notes','查看史注','button quiet')}</div></div><aside class="world-briefing-aside"><p class="context-label">走入这一场之前</p><h2>${state.showCanon?'事情已经走到这里':'先把眼前的事做完'}</h2><p>${ui.e(state.showCanon?s.currentCanon||s.summary:s.task||beat.want||s.summary)}</p>${state.showCanon?`<h3>这一场的关口</h3><p>${ui.e(beat.obstacle||'人物仍须面对已经许下的约定。')}</p><p class="small muted">${ui.e(beat.next||'下一场继续承接人物与事件的后果。')}</p>`:`<ul class="world-checklist"><li>${ui.icon(blocked?'flag':'check')}<div>船体 ${state.hull}%<small>${blocked?'需要先修补漏水与结构损伤':'可承受当前航程'}</small></div></li><li>${ui.icon(blocked?'flag':'check')}<div>粮水 ${state.stock.grain} 单位<small>${blocked?'尚不足以按计划出港':'沿岸可以继续安排补给'}</small></div></li>${state.briefingChecklist?`<li>${ui.icon('book')}<div>同行的承诺<small>${ui.e(beat.decision||s.task||'听完对方的话，再答应自己的那一份。')}</small></div></li>`:''}</ul>`}${blocked?`<div class="toolbar">${ui.go('ship-repair','先修船','button')}${ui.go('supplies','补足粮水','button')}</div>`:ui.go('quest-journal','带着日志上船','button quiet')}</aside></section>`;
  }
  function dialogue(screen,state,ui){
    const s=storyScene(state),lines=s.dialogue?.length?s.dialogue:[{speaker:'叙述',text:s.summary}],n=Math.min(Math.max(0,Number(state.dialogueLine||0)),lines.length-1),line=lines[n],last=n===lines.length-1;
    const note=state.worldScenario==='重要承诺'?'答应的话，会留在接下来的航程里。':state.worldScenario==='人物拒绝'?'同伴有自己的去处；听见拒绝，也是一段关系的结果。':state.worldScenario==='历史节点'?'历史节点已定，人物仍须亲自走过。':'';
    return `<section class="dialogue-scene" style="background-image:linear-gradient(#071f2922,#071f2988),url('${ui.sceneURL(s.id)}')"><div class="dialogue-context"><span>${ui.e(s.year)}</span><span>${ui.e(s.title)}</span>${ui.go('history-notes','史注','button quiet')}</div>${state.dialogueLog?`<aside class="dialogue-history"><h2>方才说过的话</h2>${lines.slice(0,n+1).map(l=>`<p><strong>${ui.e(l.speaker)}</strong><span>${ui.e(l.text)}</span></p>`).join('')}</aside>`:''}<div class="dialogue-box"><div class="dialogue-progress" aria-label="对白进度">${lines.map((_,i)=>`<i class="${i<=n?'read':''}"></i>`).join('')}</div><small class="muted">${n+1} / ${lines.length} · ${last?'话已说完':'话还未说完'}</small><h2>${ui.e(line.speaker)}</h2><p class="speech">${ui.e(line.text)}</p>${note?`<p class="world-dialogue-note">${note}</p>`:''}<footer><div class="toolbar">${ui.action('set','上一句','button quiet',{key:'dialogueLine',value:n-1,disabled:n===0})}${ui.action('toggle',state.dialogueLog?'收起回看':'回看对白','button quiet',{key:'dialogueLog'})}</div><div class="toolbar">${last?ui.go('quest-detail','记下接下来的事','button primary'):ui.action('set','继续对白 '+ui.icon('arrow'),'button primary',{key:'dialogueLine',value:n+1})}</div></footer></div></section>`;
  }
  function decision(screen,state,ui){
    const s=state.selectedScene?storyScene(state):data().scenes.find(x=>x.id==='zheng_a2_s7'),beat=s.dramaticBeat||{},prize=s.id==='zheng_a2_s7',pending=state.worldScenario==='结果待发生',short=state.silver<380;
    return ui.pageHead('眼前的行动与代价',prize?'这条船，怎么分？':s.title,prize?'船壳、货物、修补和人情，并不能算作同一份。':s.task||beat.want||s.summary)+`<div class="wide-split"><section><img class="world-decision-image" src="${ui.sceneURL(s.id)}" alt="${ui.e(s.title)}情境"><div class="world-decision-summary"><div><h3>你想保住什么</h3><p>${ui.e(beat.want||'自己的船位，以及同伴仍肯相信的约定。')}</p></div><div><h3>眼前有什么阻力</h3><p>${ui.e(beat.obstacle||'船有损伤，货物有归属；每一笔都得说清。')}</p></div></div>${state.decisionCompare?detailRows([['方案一','先承担船壳与修补责任'],['方案二','先清点货物，留下归还记录'],['共同约束','剧情结果已定，局部安排保留不同反馈']]):`<p class="inline-note">本场的文学正线已经确定。这里记下局部安排，不改写出生、受抚或父子分途等历史节点。</p>`}</section><section><h2>${prize?'杜七在等你开口':'把答应的事讲清楚'}</h2>${pending?`<div class="world-decision-selected"><h3>已记下：${prize?'留下船壳，承担修补':ui.e(beat.decision||'完成眼前的安排')}</h3><p>决定已经记录；结果仍需通过接下来的故事与行动发生。修船费用尚未扣除。</p>${ui.go('quest-journal','查看这份约定','button')}</div>`:`<p class="muted">${ui.e(prize?'他出了兵器，也截住了退路。你要船，往后修船的钱得自己去找。':beat.decision||s.task||'先听见他人的代价，再决定自己承担哪一份。')}</p>`}${state.fixedDecision?`<ol class="world-start-steps"><li><b>事已发生</b><span>${ui.e(s.currentCanon||s.summary)}</span></li><li><b>仍需完成</b><span>${ui.e(s.task||'将许下的安排逐件做完。')}</span></li></ol>${ui.go('dialogue','继续这一场','button primary')}`:`<div class="decision-options">${ui.action('choose',`<strong>${prize?'留下船壳，承担修补':'按约定推进眼前事务'}</strong><p>${prize?'杜七取兵器与约定货份，旧货归属仍待交代。':'承认人物的处境，记录本场的行动责任。'}</p><small>${short?'现银不足以完成后续修补，需先安排资金':'预计后续修补 380 两；本次仅记录选择'}</small>`,'decision-option '+(state.choice==='keep-hull'?'selected':''),{item:'keep-hull',message:'已记下这项责任；后续行动尚需逐件完成。',disabled:pending})}${ui.action('choose','<strong>先清点未结清的事</strong><p>记录货物归属、同行的付出与尚待兑现的承诺。</p>','decision-option '+(state.choice==='record-cargo'?'selected':''),{item:'record-cargo',message:'尚未结清的责任已留在本次安排中。',disabled:pending})}</div>`}${short?`<div class="world-status is-warning"><h3>现银 ${state.silver} 两 · 修补还差 ${380-state.silver} 两</h3><p>承诺可以先记下，修补须另行筹措；不会在这里扣成负数。</p>${ui.go('accounts','先核对账册','button')}</div>`:''}<div class="toolbar">${ui.go(prize?'prize-distribution':'quest-detail',prize?'查看分利':'查看接下来的事','button primary')}${ui.go('relationships','想想同行的人','button quiet')}</div></section></div>`;
  }
  function history(screen,state,ui){
    const s=storyScene(state),h=s.history||{note:'本场为历史改编，具体对白与心理为文学重建。',sources:[]},label=state.worldScenario||({historical:'史实骨架',adaptation:'历史背景与文学重建',fiction:'原创场面'}[h.level]||'本场创作边界');
    return ui.pageHead('史实与创作边界','史书之外，故事之中','在可靠的历史骨架之间，辨认人物生活与文学想象。')+`<div class="wide-split"><article class="paper"><span class="world-history-level">${ui.e(label)}</span><p class="context-label">${ui.e(s.year)} · ${ui.e(s.title)}</p><h2>本场说明</h2><p>${ui.e(h.note)}</p><h3>本场登记来源</h3><ol class="world-history-sources">${(h.sources||[]).map(x=>`<li>${ui.e(x.title)}${x.url?`<small>${ui.e(x.url)}</small>`:''}</li>`).join('')||'<li>暂无单列来源；请以本场创作说明为边界。</li>'}</ol><p class="small">插图与对白帮助叙事；不能作为历史现场或逐字引语的证据。</p></article><aside class="world-history-aside"><h2>怎样阅读这些标识</h2>${[['历史骨架','年表、战事、受抚与家庭的重要节点，按来源等级说明。'],['晚出材料','成书年代与叙述立场需要另看，传闻不直接变成定论。'],['研究推断','将资料间的联系与推理过程说明，保留不能坐实的部分。'],['原创场面','私人对白、合成人物和具体冒险服务文学叙事。']].map(([a,b])=>`<section class="${label===a?'is-active':''}"><h3>${a}</h3><p>${b}</p></section>`).join('')}<div class="toolbar">${ui.go('scene-briefing','回到这一场','button')}${ui.go('chapter-select','换一场阅读','button quiet')}</div></aside></div>`;
  }
  function ending(screen,state,ui){
    const p=state.worldScenario;
    return `<section class="cinema-scene world-ending" style="background-image:url('${ui.sceneURL('zheng_a6_s5')}')"><div class="cinema-copy"><p class="context-label">1646 · 本卷终</p><h1>未回的船</h1><p>船没有等到旧主人回来。<br>留在这里的人，仍得使它开出去。</p><p class="small">芝龙北去，成功留海。阿旺的工具箱终于到了家。</p>${p==='章节回顾'?`<div class="world-ending-years">${data().acts.map((a,i)=>`<span><b>${'一二三四五六'[i]}</b>${ui.e(a.title)} · ${ui.e(a.years)}</span>`).join('')}</div>`:p==='固定历史结局'?`<div class="world-ending-summary"><div><h3>父亲北去</h3><p>1646年，芝龙离开福建。私人约定不能改写这一历史方向。</p></div><div><h3>儿子留海</h3><p>成功继续面对船、军务与未完的家事，故事停在此处。</p></div></div>`:p==='首次终章'?`<div class="world-ending-summary"><div><h3>留在岸上的</h3><p>一口送到家的工具箱，和终于不必再等的旧约。</p></div><div><h3>仍须出海的</h3><p>有伤的船、未完的修补，还有要亲自承担的名字。</p></div></div>`:''}<div class="toolbar">${ui.go('chronicle','回望这段生涯','button primary')}${ui.go('chapter-select','重读篇章')}${ui.go('main-menu','回到首页','button quiet')}</div></div></section>`;
  }
  function compass(ui,heading=78){return `<svg class="world-compass" viewBox="0 0 160 160" role="img" aria-label="船艏朝向 ${heading} 度，风从东北来"><circle cx="80" cy="80" r="58"/><circle cx="80" cy="80" r="46"/>${[['北',80,13],['东',148,85],['南',80,155],['西',13,85]].map(([t,x,y])=>`<text x="${x}" y="${y}">${t}</text>`).join('')}<g transform="rotate(${heading} 80 80)"><path class="needle" d="M80 29L89 99 80 89 71 99Z"/></g><path class="wind-arrow" d="M127 33L110 50M110 40V50H120"/><circle cx="80" cy="80" r="4"/></svg>`;}
  function sailing(screen,state,ui){
    const near=Number(state.voyageProgress||24)>90,emergency=Number(state.hull)<30,against=state.weather==='逆风',progress=Number(state.voyageProgress||24),heading=state.heading||78;
    return `<section class="sailing-scene world-sailing" style="background-image:url('${ui.sailingImage}')"><div class="hud-objective"><p class="context-label">当前航程 · 福建外海</p><h2>${emergency?'先保住船，再走下一程':near?'${DEST}的岸，已在前方'.replace('${DEST}',ui.e(state.destination)):against?'借助转向，迎着风走':'顺着这阵风，去'+ui.e(state.destination)}</h2><p>${emergency?'船体受损，先分派损管并寻找避风处。':near?'收帆减速，准备核对泊位与入港凭据。':'货已装妥，家书还在怀中。'}<br>下一站：${ui.e(near?state.destination:state.route==='直航'?'外海航段':midway(state))}</p><div class="world-voyage-progress" aria-label="航次已完成 ${progress}%">${Array.from({length:8},(_,i)=>`<i class="${i<progress/12.5?'done':''}"></i>`).join('')}</div><div class="world-voyage-stages"><span>出港</span><span>${near?'近岸靠泊':'海上航段'}</span><span>到港</span></div>${ui.go('quest-detail','查看这程的约定','button quiet')}</div><aside class="hud-compass">${compass(ui,heading)}<p>航向 ${String(heading).padStart(3,'0')}° · ${against?'迎风转向辅助':'东北来风'}</p>${ui.go('weather-wind','风向与天气','button quiet')}</aside>${emergency?`<div class="world-hud-alert"><strong>船体 ${state.hull}% · 需要应急处理</strong><p>临时补漏只能争取时间，仍需到港修复。</p>${ui.go('battle-damage','安排损管','button')}</div>`:against?`<div class="world-hud-alert"><strong>逆风航行辅助已介入</strong><p>分段转向维持前进；可继续点选海面调整航向。</p>${ui.go('route-plan','重新看一眼航路','button quiet')}</div>`:''}<aside class="world-hud-minimap">${chart(ui,false,{...state,miniMap:true})}${ui.go('sea-chart','小海图 · 展开','button quiet')}</aside><div class="hud-sailing-bottom"><div class="hud-instruments">${ui.metric('航速',state.speed,'节')}${ui.metric('船体',state.hull,'%')}${ui.metric('航程',progress,'%')}${ui.metric('目的港',state.destination)}</div>${ui.go(near?'destination-detail':'sea-chart',near?'准备靠泊':'展开海图','button primary')}</div><p class="hud-help">左键定向　滚轮缩放　右键环绕　${ui.go('settings','运镜设置','button quiet')}</p></section>`;
  }

  function seaChart(screen,state,ui){
    const p=port(state),unverified=state.chartFilter==='unverified',restricted=state.chartFilter==='restricted';
    const names=state.chartFilter==='known'?['澳门','厦门','泉州','平户']:Object.keys(PORTS);
    return ui.pageHead('航路与消息','海图','看清下一处港口，也留意海上新来的旗。',ui.go('sailing-hud','收起海图'))+`<nav class="world-port-selector" aria-label="选择目的港">${names.map(name=>ui.action('set',name,`button ${name===state.destination?'selected':''}`,{key:'destination',value:name})).join('')}</nav><div class="map-layout">${chart(ui,false,state)}<aside class="world-map-aside"><p class="context-label">已选目的港 · ${ui.e(p.region)}</p><h2>${ui.e(state.destination)}</h2><p>${ui.e(p.notice)}</p>${detailRows([['当前船位','厦门东北外海'],['估计距离',p.distance+' 海里'],['航路',state.routeConfirmed?'已确认 · '+(state.route||'沿岸'):'尚未确认'],['进港消息',restricted?'通行范围待查':unverified?'南来船主转述 · 尚未核实':'有熟识船主可问']])}${unverified?`<div class="world-status is-warning"><h3>先核实吕宋的入港条件</h3><p>转述只证明有这条消息。先找通事与凭据，不保证当地一定接纳。</p>${ui.go('intelligence','核对消息来处','button')}</div>`:restricted?`<div class="world-status is-warning"><h3>这一段航区有往来限制</h3><p>当前凭据的适用范围尚未核对，不能直接把锚地当作可自由进出的港。</p>${ui.go('sea-permits','核对通行凭据','button')}</div>`:''}${ui.go('route-plan',state.routeConfirmed?'核对已定航路':'规划这条航路','button primary')}${ui.go('destination-detail','查看目的港')}${ui.go('intelligence','对照海上情报','button quiet')}</aside></div>`;
  }
  function destination(screen,state,ui){
    const p=port(state),needs=state.worldScenario==='需要凭据',damaged=state.worldScenario==='设施受损',near=state.nearPort,approved=state.entryApproved;
    return ui.pageHead('目的港 · '+p.region,p.title,p.notice,ui.go('sea-chart','回到海图'))+`<div class="wide-split"><section><img class="world-port-image" src="${ui.sceneURL(p.image)}" alt="${ui.e(p.title)}的故事情境"><div class="world-port-facilities">${p.facilities.map((x,i)=>`<div><strong>${x}</strong><span>${damaged&&i===0?'受损 · 暂停':near?'到港后可问':'先核对当日情况'}</span></div>`).join('')}</div>${detailRows([['可询问的人',ui.e(p.contact)],['补给范围',ui.e(p.supply)],['往来货品',ui.e(p.goods)]])}</section><aside class="world-map-aside"><p class="context-label">进港前准备</p><h2>${needs?'先把凭据备齐':damaged?'港内仍在收拾残局':near?'已接近靠泊范围':approved?'已收到入港回应':'先问岸上的规矩'}</h2>${detailRows([['查验事项',ui.e(p.entry)],['与泊地距离',near?'0.8 海里':p.distance+' 海里'],['泊位消息',needs?'等待查验':damaged?'仅外侧临时泊位':approved?'引航已回应':'尚待联系'],['修理与装卸',damaged?'船坞受损，木作有限':'依当日安排']])}${needs?`<div class="world-status is-warning"><h3>缺少通事与入港凭据</h3><p>暂在外海等候。不可将开往这里的航路当作已经取得进港许可。</p>${ui.go('sea-permits','查看凭据与海令','button')}</div>`:damaged?`<p class="inline-note">先问能修什么、能装什么，再付费用。部分设施受损时，补给与修理能力会不同。</p>`:state.destination==='平户'?`<p class="inline-note">吉平熟识货行；川内浦还有等你回信的人。到港并不替你完成交货或家里的约定。</p>`:`<p class="inline-note">传来的消息会过时。到港前，再核对一遍联系人与往来限制。</p>`}<div class="toolbar">${near||approved?ui.action('open','联系泊位 · 查看港口','button primary',{key:'destination',value:state.destination,target:'port-hub',disabled:needs}):ui.go('route-plan','设为这一程目的港','button primary')}${state.destination==='平户'?ui.go('letters','读家书','button'):ui.go('relationships','看看本港旧识','button')}${ui.go('intelligence','核对港口消息','button quiet')}</div></aside></div>`;
  }
  function route(screen,state,ui){
    const p=port(state),direct=state.route==='直航',grain=Number(state.stock.grain||0),required=direct?110:80,short=grain<required,confirmed=!!state.routeConfirmed,days=Math.max(1,p.days+(direct?-1:1));
    return ui.pageHead('航路安排','这一程，怎样走','把停靠、补给与风险说清楚，再叫人解缆。',ui.go('sea-chart','返回海图'))+`<div class="map-layout">${chart(ui,true,state)}<aside class="world-map-aside"><p class="context-label">从当前船位出发</p><h2>厦门外海 → ${ui.e(state.destination)}</h2><div class="world-route-options">${ui.action('set','<strong>沿岸稳行</strong><p>保留途中补给与问路的机会，绕行会增加时间。</p>',`decision-option ${!direct?'selected':''}`,{key:'route',value:'沿岸'})}${ui.action('set','<strong>外海直航</strong><p>减少停靠，需多备粮水；海况变化时退路更少。</p>',`decision-option ${direct?'selected':''}`,{key:'route',value:'直航'})}</div><div class="world-route-cost"><div><span>估计航程</span><strong>${days} 日</strong></div><div><span>粮水底线</span><strong>${required}</strong></div><div><span>中途停靠</span><strong>${direct?'0':'1'} 处</strong></div></div><ol class="world-route-checks"><li><span>当前船体</span><strong>${state.hull}%</strong></li><li><span>现有粮水</span><strong class="${short?'negative':''}">${grain} / ${required}</strong></li><li><span>途中安排</span><strong>${direct?'外海守望':state.route==='沿岸'?midway(state):'选择沿岸后安排泊点'}</strong></li><li><span>到港查验</span><strong>${ui.e(p.entry)}</strong></li></ol>${confirmed?`<div class="world-route-confirmed"><strong>${ui.icon('check')} 航路已定：${ui.e(state.route||'沿岸')}往${ui.e(state.destination)}</strong><p>下达出港安排后，可在航行页继续核对目标与风信。${state.routeConfirmedAt?ui.e(state.routeConfirmedAt):'本次出港安排'}</p>${ui.go('sailing-hud','回到这条航路','button primary')}</div>`:short?`<div class="world-status is-warning"><h3>粮水还差 ${required-grain} 单位</h3><p>先补给，或改选所需粮水较少的沿岸安排。确认前不推进航程。</p>${ui.go('supplies','补足出港粮水','button primary')}</div>`:`<div class="world-status"><h3>已具备本次演示的出港补给</h3><p>${direct?'途中减少停靠，留意风浪与船体。':'保留一处补给安排，仍需到港核对消息。'}</p></div>`}<div class="toolbar">${ui.action('route-confirm',confirmed?'再次确认这条航路':'确认航路 · 出发','button primary',{disabled:short})}${ui.go('supplies','核对补给','button quiet')}</div></aside></div>`;
  }
  function weather(screen,state,ui){
    const variants={当前:{name:'东北风 · 尚可稳行',wind:14,wave:1.4,angle:45,heading:78,visibility:'良好',advice:'风还在东北。照着眼前的帆势走，入夜以前，再看一次天。',speed:'8.6',forecast:[14,15,18,16,13,12],seas:[12,16,20,18,15,12]},有利风:{name:'顺风 · 可以展帆',wind:12,wave:1.1,angle:65,heading:245,visibility:'良好',advice:'这阵风肯送你一程。帆可以展开，别忘了让后船跟上。',speed:'9.2',forecast:[12,13,14,12,11,10],seas:[8,12,15,12,10,9]},逆风:{name:'逆风 · 分段转向',wind:16,wave:1.8,angle:35,heading:32,visibility:'尚可',advice:'风不肯顺你，先让船走起来。别把一船人，留在原地跟它赌气。',speed:'4.6',forecast:[16,17,16,15,13,12],seas:[18,20,22,18,15,12]},无风:{name:'无风 · 保留补给',wind:1,wave:.3,angle:0,heading:78,visibility:'良好',advice:'帆不动，人的手还可以动。先分清水，再商量谁与谁合力划。',speed:'1.2',forecast:[1,1,2,3,4,6],seas:[3,3,4,5,6,7]},风暴临近:{name:'风暴临近 · 寻找避风处',wind:24,wave:3.6,angle:100,heading:78,visibility:'正在变差',advice:'云脚压低了。先收帆、收拢队形，别等第一道浪上甲板才找岸。',speed:'3.1',forecast:[18,21,24,28,25,20],seas:[20,27,35,42,37,28]}};
    const w=variants[state.weatherMode]||variants.当前,storm=state.weatherMode==='风暴临近',calm=state.weatherMode==='无风',poly=values=>values.map((v,i)=>`${40+i*100},${150-v*3}`).join(' ');
    return ui.pageHead('风、海与可走的路','天色与风信','风向影响效率与表现；逆风仍保留可用的操船方式。',ui.go('sailing-hud','返回航行'))+`<div class="world-weather"><section class="world-weather-current"><p class="context-label">瞭望与帆势</p><h2>${w.name}</h2><svg class="world-weather-rose" viewBox="0 0 240 240" role="img" aria-label="风从${calm?'不定方向':w.angle+'度方向'}来，船艏${w.heading}度"><circle class="ring" cx="120" cy="120" r="85"/><circle class="ring" cx="120" cy="120" r="60"/><path class="sector" d="M120 120L60 60A85 85 0 0145 160Z"/>${[['北',120,17],['东',225,125],['南',120,235],['西',15,125]].map(([t,x,y])=>`<text x="${x}" y="${y}">${t}</text>`).join('')}<g transform="rotate(${w.angle} 120 120)"><path class="arrow" d="M120 42L128 108H123V174H117V108H112Z"/></g><g transform="rotate(${w.heading} 120 120)"><path d="M120 78L130 140 120 131 110 140Z" fill="none" stroke="#b7d4d1" stroke-width="2"/></g></svg><div class="stat-row">${ui.metric('风速',w.wind,'米/秒')}${ui.metric('浪高',w.wave,'米')}</div>${detailRows([['能见度',w.visibility],['辅助航速',w.speed+' 节'],['最近避风处','大员东北锚地']])}</section><section class="world-weather-forecast"><p class="context-label">未来六个时段 · 示意预测</p><h2>${storm?'风浪抬高，趁早转入避风水域':calm?'缓慢起风以前，别耗尽人的力气':'保持观察，给下一次转向留出余地'}</h2><svg class="world-forecast-svg" viewBox="0 0 590 190" role="img" aria-label="未来风速与风浪示意变化">${[30,90,150].map(y=>`<line class="world-forecast-grid" x1="35" y1="${y}" x2="550" y2="${y}"/>`).join('')}<polyline class="world-forecast-line" points="${poly(w.forecast)}"/><polyline class="world-forecast-wave" points="${poly(w.seas)}"/>${w.forecast.map((_,i)=>`<text x="${40+i*100}" y="180" text-anchor="middle">${i+1} 时段</text>`).join('')}</svg><div class="world-forecast-legend"><span><i></i> 风速趋势</span><span><i class="wave"></i> 风浪趋势</span><span>趋势示意，非实测预报</span></div><div class="world-weather-outlook">${[['帆势',storm?'先收帆':calm?'保持轻帆':'随风调整'],['队形',storm?'收拢守望':'保持照应'],['补给',calm?'核对淡水':'按计划保留'],['航路',storm?'优先避风':'继续核对']].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="world-weather-advice"><div><blockquote>“${w.advice}”</blockquote><p>阿旺 · 领航建议</p></div><div><h3>${storm?'现在可以做的事':calm?'同伴与航程':'下一步的安排'}</h3><p>${storm?'调整航路前往避风处，同时检查损管与船帆。':calm?'检查粮水与士气，再安排合力操船；不要把无风变成硬性的停摆。':'留意帆面与僚船的距离。天气改变时，海图与当前目标仍可随时查看。'}</p><div class="toolbar">${ui.go('route-plan',storm?'寻找避风路线':'调整航路','button primary')}${ui.go(calm?'supplies':'settings',calm?'核对粮水':'航行辅助','button')}</div></div></div></section></div>`;
  }
  function encounter(screen,state,ui){
    const p=state.worldScenario,types={身份不明:{title:'远处的旗，还认不清',desc:'一条小船靠近外沿，主船仍留在风下。先看人数、帆势和退路。',scene:'zheng_a3_s1',identity:'尚未辨明',range:'中距离',goal:'先辨认，再接近',observations:[['旗帜','旗面折着，颜色不足以确认来历。'],['船位','小艇在前，主船留有转向余地。'],['同伴','瞭望手等待你的下一道指令。']],primary:'示意停船 · 试探来意',story:'zheng_a3_s1'},索路收费:{title:'那面旗，又来了',desc:'阮老六的收费艇停在外沿，主船仍留着能退的距离。',scene:'zheng_a1_s6',identity:'疑似阮老六部众',range:'近距离',goal:'先看清谁在拿钱',observations:[['旧物','上次留下的木筹还在，可以先认旧筹。'],['船位','收钱副手向船尾看，担心两船挤翻小艇。'],['风险','交钱不一定保平安，开炮也会牵连伙计。']],primary:'出声交涉 · 先认旧筹',story:'zheng_a1_s6'},扣船盘查:{title:'拖索已经伸过来了',desc:'盘查船要求停船核货。通事、纸面和船员的酬银，都成了眼前的事。',scene:'zheng_a3_s9',identity:'吕宋盘查船',range:'已接触',goal:'先保船员与退路',observations:[['凭据','纸面内容与通事的说法需要核对。'],['船位','拖索限制转向，船尾尚有脱离机会。'],['同伴','安东熟悉水路；要听清他的领航安排。']],primary:'听安东说明 · 查看盘查',story:'zheng_a3_s9'},同行求助:{title:'同行的船，帆已垂下来',desc:'无风已经拖了数日。依斯迈的船靠近，两船都在算剩下的淡水。',scene:'zheng_a3_s10',identity:'依斯迈的同行船',range:'可交谈',goal:'谈清交换，再一起划',observations:[['补给','淡水可以换，不能假装还有无限余量。'],['人手','共同划行需要双方同意与轮换。'],['关系','这是一份具体合作，不是一键增加的好感。']],primary:'谈淡水与合力划行',story:'zheng_a3_s10'}};
    const t=types[p]||{...types.索路收费,range:'外沿守望'};
    return ui.pageHead('海上遭遇',t.title,t.desc)+`<div class="wide-split"><section class="world-encounter-image"><img src="${ui.sceneURL(t.scene)}" alt="${ui.e(t.title)}的叙事情境"><div class="world-encounter-flags">${ui.pill('距离：'+t.range)}${ui.pill('身份：'+t.identity,p==='扣船盘查'?'danger':'')}${ui.pill('船体：'+state.hull+'%')}</div><div class="world-encounter-observations">${t.observations.map(([a,b])=>`<div><strong>${a}</strong><p>${b}</p></div>`).join('')}</div></section><aside><p class="context-label">眼前的判断</p><h2>${t.goal}</h2><p class="muted">${p==='同行求助'?'同伴也有自己的船、人和底线。先说清交换的份量，再安排各自承担的事。':'留出后退与转向的海面，别让第一句喊话替所有人决定要不要动手。'}</p><div class="world-encounter-actions">${openScene(ui,t.story,t.primary,'dialogue','button primary')}${ui.go(p==='同行求助'?'supplies':p==='扣船盘查'?'sea-permits':'battle-orders',p==='同行求助'?'核对可以交换的补给':p==='扣船盘查'?'核对船货与凭据':'叫船员戒备','button')}${ui.go('intelligence','看看这一路传来的消息','button')}${ui.go('sea-chart','保留退路 · 看海图','button quiet')}</div><p class="inline-note">交涉不保证安全。船位、退路和同伴的意愿，都在这次安排之内。</p></aside></div>`;
  }
  function pause(screen,state,ui){
    const battle=state.pauseContext==='battle',dirty=state.unsavedChanges,phase=state.pauseContext==='voyage'?'航行指令已暂歇':battle?'炮火与令旗之间':'眼前航程暂歇';
    return ui.pageHead('暂歇一刻','海上的事，等你回来','此处不推进船员、经济或剧情；回去以后，继续眼前的安排。')+`<div class="world-pause-layout"><section><img class="world-pause-scene" src="${battle?ui.sceneURL('zheng_a5_s4'):ui.sailingImage}" alt="${battle?'战术暂停中的舰阵':'暂歇中的航区'}"><div class="world-pause-status">${ui.icon(battle?'flag':'anchor')}<span>${phase} · ${battle?'料罗湾外海':'福建外海 → '+ui.e(state.destination)}</span></div><div class="stat-row">${ui.metric('船体',state.hull,'%')}${ui.metric(battle?'本舷余弹':'银两',battle?state.leftShots:state.silver,battle?'发':'两')}${ui.metric('船员',state.crew,'人')}</div>${dirty?`<div class="world-status is-warning"><h3>眼前的安排还未保存</h3><p>修补、买卖与新接的约定，只留在当前会话里。离开前可另存一份航程。</p>${ui.go('save-game','先留下这段航程','button primary')}</div>`:state.pauseContext==='voyage'?`<div class="world-status"><h3>仍在海上，不必赶着答应下一件事</h3><p>可以先看日志、检查粮水，再回到操船。</p>${ui.go('quest-journal','先看日志','button quiet')}</div>`:''}</section><nav class="world-pause-menu" aria-label="暂停菜单">${ui.go(battle?'battle-hud':'sailing-hud',(battle?'回到战术指挥':'继续航程')+' <span>›</span>')}${ui.go('save-game','保存航程 <span>›</span>')}${ui.go('load-game','读取航程 <span>›</span>')}${ui.go('settings','设置 <span>›</span>')}${ui.go('tutorial','操作帮助 <span>›</span>')}${ui.go('main-menu','返回首页 <span>›</span>')}</nav></div>`;
  }
  const render={'main-menu':menu,'new-career':career,'load-game':saves,'save-game':saves,settings,accessibility:settings,laboratory,'experiment-detail':laboratory,'chapter-select':chapters,'scene-briefing':briefing,dialogue,decision,'history-notes':history,ending,'sailing-hud':sailing,'sea-chart':seaChart,'destination-detail':destination,'route-plan':route,'weather-wind':weather,'sea-encounter':encounter,'pause-menu':pause};
  GameUI.registerRenderer(ids,(screen,state,ui)=>render[screen.id](screen,view(screen,state),ui));
})();
